impl AntiWedge<MultiVector> for NullSphereAtOrigin {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div
    //      f32        0        3        0
    //    simd2        0        2        0
    //    simd3        0        3        0
    //    simd4        0        1        0
    // Totals...
    // yes simd        0        9        0
    //  no simd        0       20        0
    fn anti_wedge(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        return MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([other[e5] * self[e1234], 1.0]) * Simd32x2::from([1.0, 0.0]),
            // e1, e2, e3, e4
            Simd32x4::from(self[e1234]) * other.group4().with_w(other[e45]),
            // e5
            0.0,
            // e41, e42, e43, e45
            (Simd32x3::from(self[e1234]) * other.group6().xyz()).with_w(0.0),
            // e15, e25, e35
            Simd32x3::from(0.0),
            // e23, e31, e12
            Simd32x3::from(self[e1234]) * other.group8(),
            // e415, e425, e435, e321
            Simd32x3::from(0.0).with_w(other[e3215] * self[e1234]),
            // e423, e431, e412
            Simd32x3::from(self[e1234]) * other.group9().yzw(),
            // e235, e315, e125
            Simd32x3::from(0.0),
            // e1234, e4235, e4315, e4125
            (Simd32x2::from([other[e12345] * self[e1234], 0.0]) * Simd32x2::from([1.0, 0.0])).with_zw(0.0, 0.0),
            // e3215
            0.0,
        );
    }
}
